import{_ as a,o as e,c as p,a3 as t}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/14-从中流化的“1955年体制”到阶层化的“2005年体制”.md","filePath":"books/xialiu-shehui/14-从中流化的“1955年体制”到阶层化的“2005年体制”.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/14-从中流化的“1955年体制”到阶层化的“2005年体制”.md"};function s(i,_,r,n,l,d){return e(),p("div",null,[..._[0]||(_[0]=[t('<h2 id="从中流化的-1955年体制-到阶层化的-2005年体制" tabindex="-1">从中流化的“1955年体制”到阶层化的“2005年体制” <a class="header-anchor" href="#从中流化的-1955年体制-到阶层化的-2005年体制" aria-label="Permalink to &quot;从中流化的“1955年体制”到阶层化的“2005年体制”&quot;">​</a></h2><p>从上述意义上来讲，日本社会正处于一个剧烈转变的时期，即从战后的经济增长体制“1955年体制”朝着完全不同的社会体制进行转变。</p><p>所谓“1955年体制”，是指1955年日本自由党与民主党两大保守党派合并成立自由民主党后，形成在以后相当长的时期内由自民党一党执政的政治体制，政治学中称之为“1955年体制”。</p><p>“1955年体制”在政治上是东西方冷战时代的产物；在经济上则正好与日本经济高速成长时期相契合；而在消费方面，这个时期又是大众消费社会不断发展，中流社会逐渐扩大的时期。换一个角度讲，所谓“1955年体制”也可以理解为是这样一种体制，即对于社会积聚起来的财富，不再只由少数资本家阶级、权力支配阶级独占，而是让更加多的国民来参与进行平均分配，从而构筑一个中流人群占大多数的社会。也就是说，“1955年体制”所追求的是社会财富的平均分配，是全社会所有人群的“中流化”。</p><p>让我们再来看看前述的“国民生活意识调查”。1958年，“中下”与“下”的回答者合计共49%。</p><p>1958年发生了什么事情？这一年中，东京塔建成，“美智子热”狂卷日本，富士重工的“斯巴鲁360”甲壳虫家庭轿车、本田技研的“超级幼兽”摩托车、日清食品的鸡味拉面等相继面世，让人真真切切看到了一个大量生产、大量消费的时代的到来。</p><p>到了1973年仅“中”的比例即达61.3%，短短15年时间，日本已经从一个等级悬殊的社会转变为贫富差别不甚明显的中流社会，超过60%的国民认为自己属于中流阶层。</p><p>然而，2005年以后的日本社会预计将不再会有较大的经济增长。对于大部分国民来说，虽然期盼着尽快摆脱经济不景气，并且消费欲求不低，但有消费欲求并不意味着追求阶层的进一步提升以及经济的增长，因为占社会大多数的人群都是中流阶层，因此也催生了一种新的价值观，即不再谋求更进一步地缩小贫富差距（参见今田高俊著《后摩登时代的社会等级差别》）。</p><p>在这样的境况中，继续追求社会财富的平均分配、追求社会所有人群“中流化”便失去了价值，于是人们开始追求对自己来说最舒适的生活、最合适的消费，这种新的价值观已经渐露端倪。正因为如此，评论家森永卓郎所著的《年收入300万日元的轻松潇洒生活经济学》一书大受追捧，畅销不衰（森永先生自身的年收入超过3000万日元，这似乎有点讽刺）。</p><p>人人以年收入700万、800万甚至1000万日元为生活目标的时代已经成为遥远的过去，至少是几年前的事情了，如今年收入300万日元也能活出自己的精彩来，所以持有这种想法的人越来越多。当然，如果有人要追求年收入3000万日元，认为那样才是最适合自己的生活，并且进行高风险的投资，动辄牟利数十亿，那也不关我的事情，别人喜欢不断提升自己的阶层则由他去好了，本人绝不妄加评论，只要我自己最低限度的生活有所保障就可以——这类人群的心理便是如此，觉得自己目前的生活并无什么不当，并且也不想随别人一同再提高。</p><p>换言之，“1955年体制”所追求的“一亿人口中流化、平等化”的社会模式已经发生了动摇，转变为“阶层化、下流化”的新模式。</p><p>这种转变实际上自上世纪80年代起就已经潜移默化开始了，只不过当时还处在高消费社会阶段，取代“1955年体制”的新的社会模式尚未清晰地显现出来。而现在，随着经济不景气、高龄化、人口持续减少等社会结构性的剧烈变化，家庭、教育、雇佣等生活各个方面的具体的变化也渐次明朗，新的社会体制模式便越来越清晰地展现在人们面前了。</p>',12)])])}const u=a(o,[["render",s]]);export{h as __pageData,u as default};
